INSERT INTO news (title, excerpt, content, category, is_featured, image_url) VALUES
  ('Manchester Muslims launch community food bank in Moss Side', 'A new volunteer-run food bank has opened at Moss Side Islamic Centre, serving families across Greater Manchester.', 'A new volunteer-run food bank has opened at Moss Side Islamic Centre, serving families across Greater Manchester. Organisers are calling for donations of non-perishable food and volunteers to help with weekly distributions. The food bank operates every Saturday from 10am.', 'local', true, 'https://images.pexels.com/photos/6646917/pexels-photo-6646917.jpeg?auto=compress&cs=tinysrgb&w=800'),
  ('Manchester Central Mosque announces Ramadan timetable', 'Manchester Central Mosque has published its full Ramadan timetable including Taraweeh prayers and community iftars.', 'Manchester Central Mosque has published its full Ramadan timetable including Taraweeh prayers and community iftars. The mosque will host daily community iftars open to all, with priority given to students and those away from family. Volunteers are needed to help prepare and serve food.', 'local', true, 'https://images.pexels.com/photos/8460390/pexels-photo-8460390.jpeg?auto=compress&cs=tinysrgb&w=800'),
  ('Greater Manchester Muslim businesses network launches', 'A new networking group for Muslim-owned businesses across Greater Manchester held its inaugural meeting this week.', 'A new networking group for Muslim-owned businesses across Greater Manchester held its inaugural meeting this week, bringing together over 50 entrepreneurs, freelancers, and professionals. The network aims to support collaboration, mentorship, and procurement opportunities within the community.', 'community', false, 'https://images.pexels.com/photos/3184360/pexels-photo-3184360.jpeg?auto=compress&cs=tinysrgb&w=800'),
  ('Manchester Muslim students host interfaith iftar', 'Muslim students from the University of Manchester and MMU hosted an interfaith iftar welcoming students of all faiths.', 'Muslim students from the University of Manchester and Manchester Metropolitan University hosted an interfaith iftar welcoming students of all faiths. The event aimed to build understanding and friendship across communities, with over 200 attendees and speakers from several faith societies.', 'community', false, 'https://images.pexels.com/photos/8460218/pexels-photo-8460218.jpeg?auto=compress&cs=tinysrgb&w=800')
